SELECT id, customer_id, account_type, balance, status, MIN(balance) OVER (PARTITION BY customer_id, account_type ORDER BY opened_date, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_min_balance, COUNT(balance) OVER (PARTITION BY customer_id, account_type ORDER BY opened_date, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_count_balance, AVG(balance) OVER (PARTITION BY customer_id, account_type ORDER BY opened_date, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_avg_balance FROM accounts;
